#requires -Version 5.1
<#
.SYNOPSIS
Provisioniert eine lokale Coding-Umgebung auf einem Windows-Shadow-PC.
.DESCRIPTION
AuditOnly prueft Hardware, CLI-Werkzeuge, lokale Zustaende und Online-Metadaten.
Es installiert nichts und laedt keine Modelle. CLI-Werkzeuge koennen eigene
Caches/Logs schreiben oder ihren Hintergrunddienst initialisieren.
Der normale Lauf installiert fehlende Werkzeuge,
prueft das lokale Modell und erstellt ein separates VS-Code-Profil.
Modelle werden pro Rolle vorgeschlagen und nach Bestaetigung bei Bedarf geladen.
Standard-Stammverzeichnis ist der Ordner dieser PS1; -InstallRoot waehlt ein anderes Ziel.
Eine bisherige Einrichtung unter LOCALAPPDATA\ShadowLocalAI kann weiterverwendet
oder kopiert werden. Erst die Eingabe y erlaubt Aenderungen; AuditOnly fragt nicht.
Basisprogramme behalten ihre Standardpfade, Modelle den in LM Studio eingestellten Ort.
Vorhandene globale Konfiguration und fremde Modelle werden nicht ersetzt.
Das eingebettete ZIP enthaelt lesbare PowerShell-Dateien; SHA256 dient der
Integritaetspruefung, nicht als Signatur eines Softwareherstellers.
#>
[CmdletBinding()]
param(
    [ValidateNotNullOrEmpty()][string]$InstallRoot,
    [switch]$AuditOnly,
    [ValidateSet('Single','Dual')][string]$ModelMode='Dual',
    [switch]$IncludeFastModel,
    [switch]$AllowPartialGpuOffload,
    [switch]$AllowUnfitAttempt,
    [ValidateRange(1024,65535)][int]$RouterPort=1235,
    [ValidateSet('Auto','Qwen27B','GptOss20B')][string]$PreferredModel='Auto',
    [string]$ModelKey,
    [string]$ApiTokenEnvironmentVariable='SHADOW_LM_API_KEY',
    [ValidateRange(8192,65536)][int]$ContextLength=32768,
    [ValidateRange(1024,65535)][int]$Port=1234,
    [string[]]$ProjectPath=@(),
    [switch]$SkipModelDownload,
    [switch]$UpdateManaged,
    [switch]$NoShortcut
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
if(-not $PSBoundParameters.ContainsKey('InstallRoot')){
    $InstallRoot=Split-Path -Parent $MyInvocation.MyCommand.Path
}
$bundleVersion='2026.11.18.20'
